    float pca_bridge_high_shape_raw_bio_near_miss_min_shape = 2.20f;
    float pca_bridge_high_shape_raw_bio_near_miss_min_sep_scale = 0.75f;
    float pca_bridge_high_shape_raw_bio_near_miss_min_parent_balance = 0.75f;
